fn save_imported_documents(
    conn: &rusqlite::Connection,
    wave: &str,
    documents: BTreeMap<String, String>,
    workflows: &BTreeMap<String, String>,
) -> StoreResult<()> {
    for (name, content) in documents {
        conn.execute(
            "INSERT INTO wave_documents(wave_id,name,content) VALUES(?1,?2,?3)
            ON CONFLICT(wave_id,name) DO NOTHING",
            params![wave, name, content],
        )?;
    }
    for (name, content) in workflows {
        conn.execute(
            "INSERT INTO wave_workflows(wave_id,name,content) VALUES(?1,?2,?3)
            ON CONFLICT(wave_id,name) DO NOTHING",
            params![wave, name, content],
        )?;
    }
    Ok(())
}

fn sync_planning(&mut self) {
    if self.planning_sync.as_ref().map(|(repo, _)| repo) == self.scope.repo.as_ref() {
        return;
    }
    self.planning_sync = None;
    let Some(repo) = &self.scope.repo else {
        return;
    };
    if self.store.is_none() {
        return;
    }
    let result = self.runtime.block_on(async {
        let store = Arc::new(
            crate::store::open_store(&StorageConfig::sqlite(self.database.clone())).await?,
        );
        crate::ops::linear_observe::PlanningSync::start(store, repo.clone())
            .map_err(anyhow::Error::from)
    });
    match result {
        Ok(sync) => self.planning_sync = Some((repo.clone(), sync)),
        Err(error) => tracing::warn!(%error, "cannot start repository planning sync"),
    }
}

pub(crate) fn start(store: SharedStore, repo: String) -> std::io::Result<Self> {
    let runtime = tokio::runtime::Builder::new_current_thread()
        .enable_all()
        .build()?;
    let (stop, stopped) = tokio::sync::oneshot::channel();
    #[cfg(test)]
    let context = super::pm::PM_TEST_CONTEXT.try_with(Clone::clone).ok();
    let thread = std::thread::Builder::new()
        .name("planning-sync".into())
        .spawn(move || {
            let drive = async {
                tokio::select! {
                    _ = stopped => {},
                    _ = repeat_sync("comment acquisition", Duration::from_secs(15), || {
                        refresh_repository_comments(&store, &repo)
                    }) => {},
                    _ = repeat_sync("planning acquisition", Duration::from_secs(15), || async {
                        tokio::time::timeout(Duration::from_secs(5), refresh_repository_planning(&store, &repo))
                            .await.map_err(|error| OpsError::Message(error.to_string()))?
                    }) => {},
                    _ = repeat_sync("comment delivery", Duration::from_secs(1), || {
                        sync_repository_deliveries(&store, &repo, false)
                    }) => {},
                    _ = repeat_sync("planning export", Duration::from_secs(1), || {
                        super::planning_export::sync_repository_exports(&store, &repo)
                    }) => {},
                    _ = repeat_sync("field delivery", Duration::from_secs(1), || {
                        super::planning_delivery::sync_repository_fields(&store, &repo)
                    }) => {},
                    _ = repeat_sync("Task state delivery", Duration::from_secs(1), || {
                        sync_repository_deliveries(&store, &repo, true)
                    }) => {},
                }
            };
            #[cfg(test)]
            if let Some(context) = context {
                runtime.block_on(super::pm::PM_TEST_CONTEXT.scope(context, drive));
                return;
            }
            runtime.block_on(drive);
        })?;
    Ok(Self {
        stop: Some(stop),
        thread: Some(thread),
    })
}

/// Read-only delivery evidence. These rows never confer execution authority.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PlanningSyncStatus {
    pub connected: bool,
    pub changes: Vec<PlanningSyncChange>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PlanningSyncChange {
    pub id: String,
    pub field: String,
    pub state: PlanningSyncState,
    pub local_value: serde_json::Value,
    pub linear_value: Option<serde_json::Value>,
    pub error: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum PlanningSyncState {
    Pending,
    Uncertain,
    AdoptedLinear,
}

struct PlanningSyncView: View {
    let sync: PlanningSyncStatus

    var body: some View {
        VStack(alignment: .leading, spacing: Spacing.xs) {
            ForEach(sync.changes) { change in
                Text(change.text)
                    .font(Typography.body(12))
                    .foregroundStyle(.secondary)
                    .textSelection(.enabled)
                    .accessibilityIdentifier("planning-sync-\(change.id)")
            }
        }
        .accessibilityIdentifier("planning-sync")
    }
}
